async function api(path,options={}){const headers={...authHeaders(),...options.headers};let body=options.body;if(body&&!(body instanceof FormData)){headers['Content-Type']='application/json';body=JSON.stringify(body)}const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),options.body instanceof FormData?120000:options.method==='PUT'?90000:20000);authRequests.add(controller);try{const r=await fetch('/api'+path,{...options,body,headers,signal:controller.signal});if(authSealed)throw authTransitionError();runtimeVersion(r);if(!r.ok){if(r.status===401){expireAuthentication();throw authTransitionError()}let e;try{e=await r.json()}catch{e={detail:'暂时连接不上服务，请稍后重试'}}if(authSealed)throw authTransitionError();const error=Error(typeof e.detail==='string'?e.detail:'消息格式不正确，请检查后重试');error.status=r.status;error.code=typeof e.code==='string'?e.code:undefined;error.retryAfter=Number(r.headers.get('Retry-After')||0)*1000;throw error}const value=await r.json();if(authSealed)throw authTransitionError();return value}finally{clearTimeout(timeout);authRequests.delete(controller)}}
function time(v){if(!v)return '';return new Date(v).toLocaleString('zh-CN',{hour12:false,timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})}
function stableHTML(el,html){if(el.atlasHTML===html)return;const top=el.scrollTop;el.innerHTML=html;el.atlasHTML=html;el.scrollTop=top}
function atLatest(){const el=$('#thread-scroll');return el.scrollHeight-el.scrollTop-el.clientHeight<70}
function jumpLatest(){const el=$('#thread-scroll');el.scrollTop=el.scrollHeight;$('#jump-latest').hidden=true}
function updateMessages(html,follow){
 const el=$('#messages'),scroll=$('#thread-scroll'),top=scroll.scrollTop;
 const anchor=[...el.querySelectorAll('[data-turn]')].find(n=>n.getBoundingClientRect().bottom>scroll.getBoundingClientRect().top);
 const key=anchor?.dataset.turn,offset=anchor?anchor.getBoundingClientRect().top-scroll.getBoundingClientRect().top:0;
 const template=document.createElement('template');template.innerHTML=html;
 const old=new Map([...el.children].filter(n=>n.dataset.turn).map(n=>[n.dataset.turn,n]));
 const keep=[];
 for(const fresh of [...template.content.children]){
  let node=old.get(fresh.dataset.turn);
  if(node&&node.atlasHTML===fresh.innerHTML){keep.push(node);continue}
  if(node){const open=[...node.querySelectorAll('details')].map(n=>n.open);const tables=[...node.querySelectorAll('.table-scroll')].map(n=>[n.scrollTop,n.scrollLeft]);node.innerHTML=fresh.innerHTML;node.querySelectorAll('details').forEach((n,i)=>{if(open[i]!=null)n.open=open[i]});node.querySelectorAll('.table-scroll').forEach((n,i)=>{if(tables[i]){n.scrollTop=tables[i][0];n.scrollLeft=tables[i][1]}})}else node=fresh;
  node.atlasHTML=fresh.innerHTML;keep.push(node)
 }
 // Move only changed/inserted nodes; unchanged turns retain selection and focus.
 let cursor=el.firstElementChild;for(const node of keep){if(node===cursor)cursor=cursor.nextElementSibling;else el.insertBefore(node,cursor)}
 const retained=new Set(keep);[...el.children].forEach(n=>{if(!retained.has(n))n.remove()});
 if(follow)jumpLatest();else{const restored=[...el.children].find(n=>n.dataset.turn===key);scroll.scrollTop=restored?scroll.scrollTop+restored.getBoundingClientRect().top-scroll.getBoundingClientRect().top-offset:top;$('#jump-latest').hidden=atLatest()}
}
