function table(columns,rows){if(!rows.length)return '';return `<div class="table-scroll" tabindex="0"><table><thead><tr>${columns.map(c=>`<th scope="col">${esc(c.label||c.name)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${columns.map((c,i)=>`<td title="${esc(Array.isArray(row)?row[i]:row[c.name])}">${esc(Array.isArray(row)?row[i]:row[c.name])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
