function operationTrace(t){
 const trace=t.agent_trace||[],v=t.verification;
 const inherited=t.resumed_from&&Number.isInteger(t.inherited_step_count)?Math.max(0,Math.min(trace.length,t.inherited_step_count)):0;
 const current=trace.slice(inherited);
 let extra='';
 if(t.task_contract)extra+='<p>验收条件：'+esc(t.task_contract.acceptance)+'</p>';
 if(v)extra+='<p>'+(v.verified?'已核对完成证据':'尚缺完成证据：'+esc((v.missing||[]).join('、')))+'</p>';
 if(t.task_plan)extra+='<p>执行计划（Agent记录）：</p><ol>'+t.task_plan.steps.map((s,i)=>'<li>'+((t.task_plan.completed_steps||[]).includes(i)?'✓ ':'')+esc(s)+'</li>').join('')+'</ol>';
 if(t.knowledge_usage)extra+='<p>内部检索 '+esc(t.knowledge_usage.search_calls||0)+' 次 · 原文核对 '+esc(t.knowledge_usage.read_calls||0)+' 次</p>';
 const rows=steps=>steps.map(s=>{
  const receipt=s.observation||{};
  const executionLabel=['run_work_command','render_work_preview'].includes(s.tool)&&receipt.remote_receipt?({succeeded:'执行成功',failed:'执行未成功',timed_out:'执行超时',cancelled:'已停止',unknown:'执行结果待核对'})[receipt.state]:null;
  const label=executionLabel||(receipt.reused_existing_run?'复用已有成果':receipt.executed===false?'未重复执行':s.status==='failed'?'未完成':s.status==='done'?'完成':'处理中');
  return `<li>${esc(toolNames[s.tool]||s.tool)} <small>${label}</small></li>`;
 }).join('');
 const history=inherited?`<details class="inherited-trace"><summary>沿用此前 ${inherited} 条历史记录</summary><ol>${rows(trace.slice(0,inherited))}</ol></details>`:'';
 return trace.length||extra?`<details class="operation-trace"><summary>查看工作记录${trace.length?' · 本轮 '+current.length+' 条'+(inherited?' · 沿用 '+inherited+' 条':''):''}</summary>${extra}${history}${current.length?`<ol class="current-trace" start="${inherited+1}">${rows(current)}</ol>`:''}</details>`:'';
}
